"""Heartbeat staleness policy for pooled connections."""


class HealthPolicy:
    def __init__(self, idle_ttl=30.0):
        if idle_ttl <= 0:
            raise ValueError("idle_ttl must be positive")
        self.idle_ttl = float(idle_ttl)

    def is_stale(self, connection, now):
        return connection.last_heartbeat + self.idle_ttl <= now

